import { createGitHubWebhookReceiverWorker } from "./worker.ts";

export { createGitHubWebhookReceiverWorker };

export default createGitHubWebhookReceiverWorker();
import { problemResponse } from "@cyspbot/http/problem-details";
import type { GitHubWebhookReceiverDependencies } from "./github-webhooks/acceptance.ts";
import { handleGitHubWebhookRequest } from "./webhook.ts";

const defaultGitHubWebhookReceiverDependencies: GitHubWebhookReceiverDependencies = {
  now: () => new Date(),
};

export function createGitHubWebhookReceiverWorker(
  dependencies: GitHubWebhookReceiverDependencies = defaultGitHubWebhookReceiverDependencies,
): ExportedHandler<GitHubWebhookReceiverEnv> {
  return {
    fetch(request, env) {
      const url = new URL(request.url);

      if (url.pathname !== "/github/webhooks") {
        return problemResponse(404);
      }

      if (request.method !== "POST") {
        return problemResponse(405, { allow: "POST" });
      }

      return handleGitHubWebhookRequest(request, env, dependencies);
    },
  };
}
import { env, exports } from "cloudflare:workers";
import { describe, expect, it } from "vitest";

import { githubWebhookHeaders, githubWebhookTestSecret } from "../support/webhook.ts";

describe("GitHub webhook receiver Worker entrypoint", () => {
  it("accepts a signed ping for the configured GitHub App", async () => {
    const body = JSON.stringify({
      hook: {
        active: true,
      },
      zen: "Speak like a human.",
    });
    const response = await exports.default.fetch("https://example.test/github/webhooks", {
      body,
      headers: githubWebhookHeaders(
        body,
        githubWebhookTestSecret,
        "ping",
        "integration-delivery",
        env.GITHUB_APP_ID,
      ),
      method: "POST",
    });

    expect(response.status).toBe(202);
    await expect(response.json()).resolves.toEqual({
      accepted: true,
      event: "ping",
    });
  });

  it("does not serve unrelated routes", async () => {
    const response = await exports.default.fetch("https://example.test/health");

    expect(response.status).toBe(404);
    await response.body?.cancel();
  });
});
import { createGitHubWebhookReceiverWorker } from "@cyspbot/github-webhook-receiver/worker";
import type { GitHubWebhookReceiverDependencies } from "@cyspbot/github-webhook-receiver/github-webhooks/acceptance";

import { testEnv } from "./worker-env.ts";

type TestEnv = GitHubWebhookReceiverEnv;

const testNow = new Date("2026-05-24T00:00:00.000Z");

const testGitHubWebhookReceiverDependencies = {
  now: () => testNow,
} satisfies GitHubWebhookReceiverDependencies;

const githubWebhookReceiverApp = createGitHubWebhookReceiverWorker(
  testGitHubWebhookReceiverDependencies,
);

export function fetchGitHubWebhookReceiver(
  input: RequestInfo | URL,
  init?: RequestInit,
): Promise<Response> {
  return fetchWorkerWithApp(githubWebhookReceiverApp, input, init);
}

function fetchWorkerWithApp(
  app: ExportedHandler<TestEnv>,
  input: RequestInfo | URL,
  init?: RequestInit,
  env: TestEnv = testEnv,
): Promise<Response> {
  const handler = app.fetch;

  if (handler === undefined) {
    throw new Error("test app has no fetch handler");
  }

  return Promise.resolve(
    handler(new Request(input, init) as Parameters<typeof handler>[0], env, {} as ExecutionContext),
  );
}
